import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output, SimpleChanges } from '@angular/core';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { temaUsers, users } from '../../../interfaces/present.tool.interface';
import { PresentToolService } from '../../../services/present-tool/present-tool.service';
import { CdkDragDrop, DragDropModule, moveItemInArray, transferArrayItem } from '@angular/cdk/drag-drop';
import { MatMenuModule } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { NgScrollbarModule } from 'ngx-scrollbar';

@Component({
  selector: 'present-user-controller',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [AvatarComponent, ButtonComponent, IconComponent, DragDropModule, MatMenuModule, MatTooltipModule,NgScrollbarModule],
  templateUrl: './present-user-controller.component.html',
  styleUrl: './present-user-controller.component.scss'
})
export class PresentUserControllerComponent implements OnInit {
  showlsit: boolean = false;
  @Input() nPresentid: string;

  @Input() menuOpen: boolean;

  @Output() onEvent = new EventEmitter<toolEvents>();

  @Input() active_teams: temaUsers[] = [];
  @Output() active_teamsChange = new EventEmitter<temaUsers[]>();


  @Input() global_teams: temaUsers[] = [];
  @Output() global_teamsChange = new EventEmitter<temaUsers[]>();

  isLoading: boolean = true;
  dragContainer: 'A' | 'G';
  dragUser: string;
  constructor(private presentToolService: PresentToolService, private cdr: ChangeDetectorRef, private socket: SocketService) {

  }



  ngOnInit() {
    this.fetchUsers();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes["menuOpen"] && !changes["menuOpen"].firstChange) {
      if (!this.menuOpen) {
        this.showlsit = false;
      }
      this.fetchUsers();
    } else if (changes["active_teams"] && !changes["active_teams"].firstChange) {
      this.cdr.detectChanges();
    }
  }


  emitChanges() {
    this.active_teamsChange.emit(this.active_teams);
    this.global_teamsChange.emit(this.global_teams);
  }

  async fetchUsers() {
    const res = await this.presentToolService.getPresentUsers(this.nPresentid);

    const teams = res[0];
    const users = res[1];
    this.active_teams = [];
    this.global_teams = [];
    teams.forEach((team: any) => {
      const teamUsers = users.filter((user: any) => user.nTeamid == team.nTeamid && user.nPUid);
      if (teamUsers.length)
        this.active_teams.push({ ...team, users: [...teamUsers] });

      const remainUsers = users.filter((user: any) => user.nTeamid == team.nTeamid && !user.nPUid);
      if (remainUsers.length)
        this.global_teams.push({ ...team, users: [...remainUsers] });

    });



    this.isLoading = false;
    this.emitChanges();
    this.cdr.detectChanges();
  }


  async useAction(nUserid: string, cPermission: 'N' | 'D') {
    const res = await this.presentToolService.managePresentUsers(this.nPresentid, nUserid, cPermission);
    const ind = this.active_teams.findIndex((team: temaUsers) => team.users.find((user: users) => user.nUserid == nUserid));
    try {
      if (cPermission == 'N') {
        if (ind > -1) {
          const obj = this.active_teams[ind]?.users?.find(a => a.nUserid == nUserid);
          if (obj) {
            obj.nPUid = res[0].nPUid
            obj.cStatus = 'A';
          }
        }
      }
    } catch (error) {

    }
    this.emitChanges();
    this.onEvent.emit({ event: 'USER-UPDATED', data: {} })
    this.cdr.detectChanges();
  }

  async manageUserStatus(user: users) {
    user.cStatus = user.cStatus == 'A' ? 'I' : 'A';
    await this.presentToolService.managePresentUsers(this.nPresentid, user.nUserid, 'E', user.cStatus);
    if (user.cStatus == 'I') {
      this.socket.sendMessage('present-pause-user', { nPresentid: this.nPresentid, nUserid: user.nUserid })
    }
    this.cdr.detectChanges();
  }

  drop(evnt, dropContainer) {
    if (this.dragContainer == dropContainer) {
      if (this.dragContainer == 'A') {
        // -60 , 70
        if (evnt.distance.x < -60 || evnt.distance.x > 70 ) {
          // alert(1)


          this.active_teams.forEach((team: temaUsers) => {
            const user = team.users.find((user: users) => user.nUserid == this.dragUser);
            if (user) {
              user.nPUid = null;
              user.cStatus = 'A';
              let findTeam = this.global_teams.find((team: temaUsers) => team.nTeamid == user.nTeamid);
              if (!findTeam) {
                this.global_teams.push({ ...team, users: [] });
                findTeam = this.global_teams.find((team: temaUsers) => team.nTeamid == user.nTeamid);
              }
              findTeam.users.push(user);
              team.users = team.users.filter((user: users) => user.nUserid != this.dragUser);
            }
          });

          this.useAction(this.dragUser, 'D')

        }
      }
      return;
    }

    if (this.dragContainer == 'G' && dropContainer == 'A') {

      this.global_teams.forEach((team: temaUsers) => {
        const user = team.users.find((user: users) => user.nUserid == this.dragUser);
        if (user) {
          user.nPUid = team.nTeamid;
          let findTeam = this.active_teams.find((team: temaUsers) => team.nTeamid == user.nTeamid);
          if (!findTeam) {
            this.active_teams.push({ ...team, users: [] });
            findTeam = this.active_teams.find((team: temaUsers) => team.nTeamid == user.nTeamid);
          }
          findTeam.users.push(user);
          team.users = team.users.filter((user: users) => user.nUserid != this.dragUser);
        }
      });

      this.useAction(this.dragUser, 'N')
    } else if (this.dragContainer == 'A' && dropContainer == 'G') {
      this.active_teams.forEach((team: temaUsers) => {
        const user = team.users.find((user: users) => user.nUserid == this.dragUser);
        if (user) {
          user.nPUid = null;
          user.cStatus = 'A';
          let findTeam = this.global_teams.find((team: temaUsers) => team.nTeamid == user.nTeamid);
          if (!findTeam) {
            this.global_teams.push({ ...team, users: [] });
            findTeam = this.global_teams.find((team: temaUsers) => team.nTeamid == user.nTeamid);
          }
          findTeam.users.push(user);
          team.users = team.users.filter((user: users) => user.nUserid != this.dragUser);
        }
      });
      this.useAction(this.dragUser, 'D')
    }



    this.active_teams = this.active_teams.filter(a => a.users?.length);
    this.global_teams = this.global_teams.filter(a => a.users?.length);
    this.dragContainer = null;
    this.dragUser = null;

    this.emitChanges();
    this.cdr.detectChanges();
  }

  dragFrom(flag: 'A' | 'G', nUserid: string) {
    console.log('Start From')
    this.dragContainer = flag
    this.dragUser = nUserid
  }


  async manageUserRequest(user: users, cAStatus: 'A' | 'R') {

    if (cAStatus == 'A') {
      user.cStatus = "A";
      // user.isLive = true;
    }
    user.cAStatus = cAStatus;
    await this.presentToolService.manageUserRequest(this.nPresentid, user.nUserid, cAStatus);
    this.emitChanges();
    this.cdr.detectChanges();
  }
}
